async function cue() {
  if(!session.sound){announce('Sound is off. Enable sound before playing a cue.');const note=$('#sound-feedback');if(note)note.textContent='Sound is off. Enable sound first.';return;}
  if(performance.now()-lastCueAt<280)return;
  lastCueAt=performance.now();
  try{
    const Audio=window.AudioContext||window.webkitAudioContext;
    if(!Audio)throw new Error('Audio not supported');
    audioContext??=new Audio();await audioContext.resume();
    if(!session.sound)return;
    const t=audioContext.currentTime;
    for(const [hz,gain,duration] of [[196,session.volume,.16],[588,session.volume*.22,.23]]){
      const tone=audioContext.createOscillator(),env=audioContext.createGain();
      tone.type='sine';tone.frequency.setValueAtTime(hz,t);tone.frequency.exponentialRampToValueAtTime(hz*.9,t+.12);
      env.gain.setValueAtTime(.0001,t);env.gain.exponentialRampToValueAtTime(Math.max(.0001,gain),t+.006);env.gain.exponentialRampToValueAtTime(.0001,t+duration);
      tone.connect(env);env.connect(audioContext.destination);tone.start(t);tone.stop(t+duration+.02);
      tone.onended=()=>{tone.disconnect();env.disconnect();};
    }
    const n=$('#sound-feedback');if(n)n.textContent='One soft cue played. Silence resumes immediately.';
    announce('Soft cue played.');
    const rings=$('.cue-rings');if(rings){rings.classList.remove('animate');void rings.offsetWidth;rings.classList.add('animate');}
  }catch{
    session.sound=false;document.querySelectorAll('[data-action="sound"]').forEach(b=>b.textContent='Enable sound');
    const n=$('#sound-feedback');if(n)n.textContent='This browser could not play sound. All game feedback remains visible.';
    announce('Sound unavailable. The sketch remains usable in silence.');
  }
}
function downloadImage(publicMode=false) {
  const lines=publicMode?(session.selectedPoem===1?secondPoem:samplePoem):poemLines(), dark=document.documentElement.dataset.mode==='dark';
  const bg=dark?'#203e34':'#ffffff',ink=dark?'#eef6e8':'#234c42';
  const authors=!publicMode&&session.selectedPoem===0&&hasCompleteOwnPoem()?session.name:'Robin, Mina and Sol';
  const ctx=document.createElement('canvas').getContext('2d');
  ctx.font='38px sans-serif';
  const wrap=(text,width)=>{
    const rows=[];let row='';
    for(const char of Array.from(text)){
      if(row&&ctx.measureText(row+char).width>width){rows.push(row);row=char;}else row+=char;
    }
    rows.push(row);return rows;
  };
  let y=380;
  const poemText=lines.map(line=>{const rows=wrap(line,960);const text=rows.map(row=>{const t=`<text x="120" y="${y}" font-family="sans-serif" font-size="38" fill="${ink}">${esc(row)}</text>`;y+=55;return t;}).join('');y+=27;return text;}).join('');
  const rule=y+20;
  y+=80;
  const authorText=wrap(authors,1300).map(row=>{const t=`<text x="120" y="${y}" font-family="sans-serif" font-size="25" fill="${ink}">${esc(row)}</text>`;y+=40;return t;}).join('');
  const height=y+140;
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="${height}" viewBox="0 0 1200 ${height}"><rect width="1200" height="${height}" fill="${bg}"/><rect x="60" y="60" width="1080" height="${height-120}" rx="3" fill="none" stroke="${ink}" stroke-width="2"/><text x="120" y="170" font-family="Georgia,serif" font-size="60" fill="${ink}">linejam</text><text x="120" y="240" font-family="sans-serif" font-size="26" fill="${ink}">Private design sketch. Saving does not publish.</text><path d="M120 285H1080" stroke="${ink}"/>${poemText}<path d="M120 ${rule}H1080" stroke="${ink}"/>${authorText}<text x="120" y="${y+45}" font-family="sans-serif" font-size="21" fill="${ink}">Nine lines: 1, 2, 3, 4, 5, 4, 3, 2, 1 words.</text></svg>`;
  const blob=new Blob([svg],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),a=document.createElement('a');
  a.href=url;a.download='linejam-odd-garden-synthetic-poem.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  const note=$('#artifact-feedback');if(note)note.innerHTML=status('Image handed to your browser.','The complete sketch poem was prepared as an SVG. No public link was created.');
  announce('Sketch poem image handed to browser download.');
}
function replay() {const root=$('#motion-stage')||$('#main');const targets=root.querySelectorAll('.ack-sprout,.bloom-frame,.cue-rings,.button');targets.forEach(e=>e.classList.remove('animate'));void root.offsetWidth;targets.forEach(e=>e.classList.add('animate'));const note=$('#replay-note');if(note)note.textContent=document.documentElement.dataset.reduced==='true'||matchMedia('(prefers-reduced-motion: reduce)').matches?'Reduced motion: final state shown immediately. No content is delayed.':motionTreatments[currentId]?.[1]||'One acknowledgement. No loop.';announce('Motion specimen replayed. Information remains visible without animation.');}

document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;event.preventDefault();const a=button.dataset.action;switch(a){
case 'home':closeModal();go('home');break;
case 'host':session.core=true;session.host=true;session.lines=[];session.draft='';session.selectedPoem=0;go('host-entry');break;
case 'join':session.core=true;session.host=false;session.lines=[];session.draft='';session.selectedPoem=0;go('join-entry');break;
case 'lobby':closeModal();go('room-lobby');break;
case 'start':session.core=true;session.round=1;session.lines=[];session.draft='';session.selectedPoem=0;go('room-writing');break;
case 'next-round':session.round=Math.min(9,session.round+1);session.draft='';session.core=true;go('room-writing');break;
case 'reveal':case 'example-reveal':session.selectedPoem=0;go('reveal-circle');break;
case 'read':case 'step-in':session.selectedPoem=Number(button.dataset.value||0);go('poem-reading');announce(`Complete poem open. ${session.name} is reading. All nine lines are visible.`);break;
case 'circle':go('reveal-circle','success');break;
case 'recap':go('session-recap');break;
case 'archive':go('archive');break;
case 'poem':session.selectedPoem=Number(button.dataset.value||0);go('poem-detail');break;
case 'profile':go('profile');break;
case 'account':go('account-controls');break;
case 'export':go('poem-image-export');break;
case 'lobby-stage':go('lobby-presentation');break;
case 'reveal-stage':go('reveal-presentation');break;
case 'releases':go('releases');break;
case 'feed':go('releases-feed');break;
case 'help':openModal(helpContent(),'How to play Linejam');break;case 'settings':openModal(settingsContent(),'Appearance and sound');break;case 'close-modal':if($('.modal'))closeModal();else go('home');break;case 'invitation':openModal(`<h2>Invite a few people.</h2><span class="code">DEMO</span><p>This non-live sketch does not create a real room code or invitation.</p>${qr()}`,'Room invitation');break;
case 'avatar':session.avatar=button.dataset.value;document.querySelectorAll('.avatar-option').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.value===session.avatar)));announce(`${session.avatar} companion selected. Your name remains your identity.`);break;
case 'favorite':{
  if(is('error')){announce('The favorite could not be saved. Its previous state remains.');const note=$('#favorite-note');if(note)note.textContent='Not saved. Your previous favorite state remains.';break;}
  const poem=Number(button.dataset.value||0);
  if(session.favorites.has(poem))session.favorites.delete(poem);else session.favorites.add(poem);
  render();announce(session.favorites.has(poem)?'Saved as a private favorite in this sketch.':'Private favorite removed in this sketch.');
  break;
}
case 'authors':session.authors=!session.authors;render();announce(session.authors?'Author names shown. They stay visible until hidden.':'Author names hidden.');break;
case 'share-poem':go('poem-sharing');break;case 'share-recap':go('recap-sharing');break;case 'confirm-share':session.published=true;go('poem-sharing','success');break;case 'confirm-recap':session.recapPublished=true;go('recap-sharing','success');break;case 'cancel-share':go(currentId==='recap-sharing'?'session-recap':'poem-detail');announce('Sharing canceled. Existing visibility is unchanged.');break;case 'revoke':session.published=false;go('poem-detail','private');announce('Public link turned off in this state sketch.');break;
case 'download':downloadImage(button.dataset.public==='true');break;case 'print':window.print();break;
case 'sound':session.sound=!session.sound;button.textContent=session.sound?'Turn sound off':'Enable sound';document.querySelectorAll('[data-action="sound"]').forEach(b=>b.textContent=button.textContent);if(!session.sound)audioContext?.suspend();const n=$('#sound-feedback');if(n)n.textContent=session.sound?'Sound enabled by you. Choose Play cue to hear it.':'Sound off. Everything remains usable in silence.';announce(session.sound?'Sound enabled. No cue has played yet.':'Sound off.');break;case 'cue':cue();break;case 'toggle-mode':setMode(document.documentElement.dataset.mode==='dark'?'light':'dark');break;case 'replay':replay();break;case 'focus-input':$('#motion-input')?.focus();break;
case 'recover':currentState='recovery';updateURL();if(['room-recovery','guest-session-recovery'].includes(currentId))go('room-lobby');else if(['route-error','global-error','auth-callback'].includes(currentId))go('home');else{render();announce('Recovery state. The draft is retained.');}break;
case 'end-game':$('#end-confirm').innerHTML=status('End this unfinished game?','Everyone returns to the lobby. Unfinished poems stay hidden.','',`<div class="actions">${action('End game','confirm-end')}${action('Keep waiting','keep-waiting',true)}</div>`);$('#end-confirm button')?.focus();break;
case 'keep-waiting':$('#end-confirm').innerHTML=action('End this game','end-game',true);$('#end-confirm button')?.focus();break;
case 'leave':case 'close-room':openModal(`<h2>Leave this gathering?</h2><p>This sketch can return you to the entrance. No real room or person is affected.</p><div class="actions">${action('Leave room','home')}${action('Stay here','close-modal',true)}</div>`,'Confirm room action');break;
case 'confirm-end':closeModal();session.lines=[];session.draft='';go('room-lobby');break;
case 'demo-action':const feedback=$('#demo-feedback');if(feedback)feedback.innerHTML=status('Action acknowledged.','This is a native, keyboard-operable control specimen.');else announce('Action acknowledged in the component sketch.');break;
case 'reset':closeModal();session.lines=[];session.draft='';session.core=false;session.round=3;go('home');break;
}});
document.addEventListener('submit',event=>{
  event.preventDefault();
  if(event.target.id==='entry-form'){
    const input=$('#pen-name'),name=input.value.trim(),code=$('#room-code');
    input.setCustomValidity(name?'':'Enter a pen name with at least one non-space character.');
    if(!name||code&&!/^[A-Z]{4}$/.test(code.value.toUpperCase())){event.target.reportValidity();return;}
    session.name=name;session.core=true;go('room-lobby');announce(`${name} entered the local sketch room.`);
  }
  if(event.target.id==='write-form'){
    const value=$('#line-text').value.trim().replace(/\s+/gu,' ');
    if(countWords(value)!==shapeWords[session.round-1]||value.length>500||is('offline')||is('pending'))return;
    session.lines[session.round-1]=value;session.draft='';go('room-waiting','accepted');announce('Your line is in. Waiting for the group in this local sketch.');
  }
});
document.addEventListener('input',event=>{
  if(event.target.id==='line-text')session.core=true;
  if(event.target.id==='line-text'||event.target.id==='slot-input')updateCount();
  if(event.target.id==='room-code')event.target.value=event.target.value.toUpperCase().replace(/[^A-Z]/g,'');
  if(event.target.id==='pen-name')event.target.setCustomValidity('');
  if(event.target.id==='notice-draft')session.draft=event.target.value;
  if(event.target.id==='volume')session.volume=Number(event.target.value);
});
function setMode(mode) {
  preferredMode=mode;
  document.documentElement.dataset.mode=mode==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):mode;
  $('#mode').value=document.documentElement.dataset.mode;
  updateURL();
}
document.addEventListener('change',event=>{
  const id=event.target.id;
  if(id==='surface'){currentSurface=event.target.value;currentId=Object.keys(selectEntries())[0];currentState='default';session.core=false;session.draft='';updateURL();render();}
  if(id==='surface-id'){currentId=event.target.value;currentState='default';session.core=false;session.draft='';updateURL();render();}
  if(id==='state'){currentState=event.target.value;session.core=false;session.draft='';updateURL();render();}
  if(id==='mode'||id==='dialog-mode')setMode(event.target.value);
  if(id==='reduced'||id==='dialog-reduced'){document.documentElement.dataset.reduced=String(event.target.checked);$('#reduced').checked=event.target.checked;updateURL();announce(event.target.checked?'Reduced motion enabled.':'Prototype motion enabled when your device permits it.');}
});
document.addEventListener('keydown',event=>{if(event.target.id==='room-code'&&event.key==='Enter'){event.preventDefault();$('#pen-name').focus();}if(event.target.id==='line-text'&&event.key==='Enter'&&!event.shiftKey){event.preventDefault();}const modal=$('.modal');if(!modal)return;if(event.key==='Escape'){event.preventDefault();closeModal();}if(event.key==='Tab'){const focusable=[...modal.querySelectorAll('button:not(:disabled),a,input,textarea,select,summary,[tabindex="0"]')];const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
document.addEventListener('click',event=>{if(event.target.classList.contains('modal-backdrop'))closeModal();});
const query=new URLSearchParams(location.search);
currentSurface=['view','component','motion','sensory'].includes(query.get('surface'))?query.get('surface'):'view';
currentId=query.get('id')||'home';
if(!Object.hasOwn(selectEntries(),currentId))currentId=Object.keys(selectEntries())[0];
currentState=query.get('state')||'default';
preferredMode=['light','dark','system'].includes(query.get('mode'))?query.get('mode'):'light';
document.documentElement.dataset.mode=preferredMode==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):preferredMode;
document.documentElement.dataset.reduced=String(query.get('reduced')==='1'||matchMedia('(prefers-reduced-motion: reduce)').matches);
document.body.dataset.embed=String(query.get('embed')==='1');
render();
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',event=>{
  if(preferredMode!=='system')return;
  document.documentElement.dataset.mode=event.matches?'dark':'light';
  $('#mode').value=document.documentElement.dataset.mode;
  updateURL();
});
